def build_lessons(topics):
    briefs = [line.split("|") for line in LESSON_BRIEFS.strip().splitlines()]
    assert len(briefs) == 72
    assert all(len(brief) == 6 for brief in briefs)
    by_id = {t["id"]: t for t in topics}
    lessons = []
    cursor = 0
    checkpoints = {12, 24, 36, 48, 60, 69, 70, 71, 72}
    review = {
        70: ["g023", "g031", "g032", "g049", "g054", "g089", "g092", "g093", "g099", "g108", "g109", "g110", "g111", "g112", "g113", "g114", "g121", "g124", "g135"],
        71: ["g021", "g022", "g086", "g089", "g090", "g091", "g093", "g094", "g095", "g096", "g114", "g115", "g116", "g117", "g118", "g128", "g129", "g130", "g142"],
        72: ["g033", "g035", "g039", "g040", "g086", "g087", "g088", "g091", "g117", "g121", "g127", "g128", "g129", "g130", "g131", "g132", "g139", "g140", "g141", "g142", "g143", "g144"],
    }
    for no, (title, objective, model, classroom, support, homework) in enumerate(briefs, 1):
        week = (no - 1) // 3 + 1
        month = (week - 1) // 4 + 1
        level = "A1" if week <= 8 else "A2" if week <= 16 else "B1"
        if no < 70:
            size = 3 if 49 <= no <= 54 else 2
            assigned = topics[cursor:cursor + size]
            ids = [t["id"] for t in assigned]
            cursor += size
        else:
            ids = review[no]
            assigned = [by_id[tid] for tid in ids]
        focus = "; ".join(t["title"].split(". ", 1)[1] for t in assigned)
        methods = re.split(r"(?<=[.!?])\s+", without_duration(classroom))[:3]
        methods.append(f"Mashqlarda aynan {focus} farqlarini tekshirtiring; o‘quvchi bitta noto‘g‘ri shaklni tuzatib, sababini o‘zbekcha tushuntirsin.")
        methods.append("Shu vaziyatdan yangi misol tuzdiring va sherikka ma’nosini qayta ayttiring; hali o‘tilmagan shaklni mustaqil yasashni talab qilmang.")
        if no in checkpoints:
            methods[-1] = "Qoida tanlovi va mustaqil qo‘llashdagi xatolarni ichki nazorat sifatida qayd eting; bu kuzatuvni rasmiy Goethe bali bilan tenglashtirmang."
        if no == 1:
            methods = [
                "Kurs maqsadi, asosiy va yordamchi darslarning vazifasi hamda xato jurnali bilan tanishtiring; o‘quvchi o‘z shaxsiy maqsadini yozsin.",
                "26 harf va ä, ö, ü, ß ni ko‘rsatib, ism kartalari orqali harflab diktant qiling; A /aː/, E /eː/, I /iː/, J /jɔt/, V /faʊ/, W /veː/, Z /tsɛt/ harf nomlarini so‘zdagi tovushdan ajrating.",
                "Eshitib takrorlashda ei /aɪ/ (mein), ie /iː/ (sie), eu/äu /ɔʏ/ (neu/Häuser), sch /ʃ/ (Schule), ch /ç/ (ich) va /x/ (Buch), so‘z boshidagi sp/st /ʃp, ʃt/ (Sport/Stadt) ni qiyoslang.",
                "Ö va ü ni aytishda e/i uchun til holatini saqlab labni yumaloqlating; Staat/Stadt orqali unli uzunligini, ot kartalarida esa bosh harfni tekshiring.",
                "Ich/du/wir/ihr/sie/Sie kartalarini shaxs rasmlariga bog‘lang va ismni harflab aytish bilan tanishuv qiling; heiße ni hozircha tayyor ibora sifatida bering.",
            ]
        assert 3 <= len(methods) <= 5
        teacher = " ".join(methods)
        support_text = (
            without_duration(support) + " "
            f"Natijada {focus} bo‘yicha ikkita shaklni belgilang va tanlov sababini ayting. "
            "Sherik ikki aniq tuzatish taklif qilsin, muallif ularni qo‘llab mahsulotini qayta aytsin yoki yozsin."
        )
        homework_items = [
            f"{', '.join(ids)} mavzularidagi 3 tadan mashqni javobni ochmasdan qayta bajaring; kamida ikki xatoga o‘zbekcha sabab yozing.",
            without_duration(homework),
            f"«{title}» vaziyatidan 4 gapni matnga qaramasdan ovozga yozing; keyingi takrorda bitta eski xatoni topib tuzating.",
        ]
        if no in FINAL_GUIDANCE:
            final = FINAL_GUIDANCE[no]
            title, objective = final["title"], final["objective"]
            teacher = " ".join(part.format(module=OFFICIAL_MODULES[no], model=OFFICIAL_MODEL) for part in final["teacher"])
            support_text = final["support"]
            homework_items = final["homework"]
        lessons.append({
            "no": no,
            "week": week,
            "month": month,
            "level": level,
            "title": title,
            "topicIds": ids,
            "objective": objective,
            "teacherTip": teacher,
            "supportTask": support_text,
            "homework": homework_items,
            "checkpoint": no in checkpoints,
        })
    assert cursor == len(topics), (cursor, len(topics))
    return lessons


def validate(topics, lessons):
    assert len(topics) == 144
    assert len(lessons) == 72
    assert Counter(t["level"] for t in topics) == {"A1": 48, "A2": 48, "B1": 48}
    assert Counter(l["level"] for l in lessons) == {"A1": 24, "A2": 24, "B1": 24}
    assert Counter(l["week"] for l in lessons) == {week: 3 for week in range(1, 25)}
    assert Counter(l["month"] for l in lessons) == {month: 12 for month in range(1, 7)}
    topic_keys = {"id", "level", "title", "rule", "example", "translation", "questions"}
    lesson_keys = {"no", "week", "month", "level", "title", "topicIds", "objective", "teacherTip", "supportTask", "homework", "checkpoint"}
    ids = {t["id"] for t in topics}
    assert len(ids) == len(topics)
    qids = set()
    for n, topic in enumerate(topics, 1):
        assert set(topic) == topic_keys
        assert topic["title"].startswith(f"{n:03d}.")
        assert len(topic["questions"]) == 3
        for q in topic["questions"]:
            assert q["id"] not in qids
            qids.add(q["id"])
            assert q["answers"] and all(a.strip() == a and a for a in q["answers"])
            assert q["explanation"] and q["prompt"] and q["prompt"].count("___") == 1
            assert isinstance(q["caseSensitive"], bool)
    seen = set()
    first_use = {}
    topic_level = {t["id"]: t["level"] for t in topics}
    for n, lesson in enumerate(lessons, 1):
        assert set(lesson) == lesson_keys
        assert lesson["no"] == n
        assert lesson["week"] == (n - 1) // 3 + 1
        assert lesson["month"] == (lesson["week"] - 1) // 4 + 1
        assert len(lesson["topicIds"]) == len(set(lesson["topicIds"]))
        assert set(lesson["topicIds"]) <= ids
        if lesson["week"] == 24:
            assert set(lesson["topicIds"]) <= seen, "New grammar in review week"
        else:
            assert all(topic_level[tid] == lesson["level"] for tid in lesson["topicIds"])
        for tid in lesson["topicIds"]:
            first_use.setdefault(tid, n)
        seen.update(lesson["topicIds"])
        assert len(lesson["homework"]) == 3
        assert not re.search(r"\d+[–-]\d+\s*(?:daqiqa)?\s*:", lesson["teacherTip"])
        for text in [lesson["supportTask"], *lesson["homework"]]:
            assert not re.search(r"\d+(?:[–-]\d+)?\s*(?:daqiqa|soniya|minut)", text), (n, text)
        if n < 70:
            assert not re.search(r"\d+\s*(?:daqiqa|soniya|minut)", lesson["teacherTip"])
        else:
            assert OFFICIAL_MODULES[n] in lesson["teacherTip"]
            assert OFFICIAL_MODEL in lesson["teacherTip"]
            assert f"{ {70: 65, 71: 40, 72: 60}[n]} daqiqalik" in lesson["teacherTip"]
        plain_tip = re.sub(r"https?://\S+", "SOURCE.", lesson["teacherTip"])
        assert 3 <= len(re.split(r"(?<=[.!?])\s+", plain_tip)) <= 5, (n, plain_tip)
    assert seen == ids, sorted(ids - seen)
    assert max(first_use.values()) == 69
    assert len(qids) == 432
    return {
        "topics": len(topics), "topicsPerLevel": dict(Counter(t["level"] for t in topics)),
        "exercises": len(qids), "mainLessons": len(lessons), "supportLessons": len(lessons),
        "weeks": 24, "months": 6, "mainMinutes": len(lessons) * 120,
        "supportMinutes": len(lessons) * 60, "totalContactHours": len(lessons) * 180 // 60,
        "unmappedTopics": len(ids - seen), "lastNewGrammarLesson": max(first_use.values()),
        "newTopicsInWeek24": 0, "internalCheckpoints": sum(l["checkpoint"] for l in lessons),
        "officialModelModules": ["Lesen 65", "Hören 40", "Schreiben 60"],
        "teacherTipsWithoutAlternativeAgendas": 72, "homeworkWithoutTimeBudgets": 72,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--lessons-only", action="store_true", help="Regenerate lessons without writing grammar.json")
    args = parser.parse_args()
    topics = build_grammar()
    lessons = build_lessons(topics)
    result = validate(topics, lessons)
    DATA.mkdir(parents=True, exist_ok=True)
    for name, payload in (("grammar.json", topics), ("lessons.json", lessons)):
        if args.lessons_only and name == "grammar.json":
            continue
        path = DATA / name
        path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        assert json.loads(path.read_text(encoding="utf-8")) == payload
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

